package com.cryptostrategy.platform.backtesting.api.model;
import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.time.Instant;import org.junit.jupiter.api.Test;
class BacktestDomainModelTest{@Test void tradeRequiresOrderedTimesAndExactFeeComponents(){BacktestResultId result=new BacktestResultId("00000000000000000000000010");assertThrows(IllegalArgumentException.class,()->new Trade(new TradeId("00000000000000000000000011"),result,0,PositionSide.LONG,Instant.EPOCH,Instant.EPOCH,Money.of(BigDecimal.TEN),Money.of(BigDecimal.TEN),new Quantity(BigDecimal.ONE),Money.of(BigDecimal.ONE),Money.of(BigDecimal.ONE),Money.of(BigDecimal.ONE),BigDecimal.ZERO,Money.of(BigDecimal.TEN),ExitReason.STRATEGY_SELL));}@Test void moneyAndQuantityAreCanonicalAndNonnegative(){assertEquals(12,Money.of(new BigDecimal("1")).value().scale());assertThrows(IllegalArgumentException.class,()->Money.of(BigDecimal.valueOf(-1)));assertThrows(IllegalArgumentException.class,()->new Quantity(BigDecimal.ZERO));}}
